expected.test_program:
assert parse_csv_ints('1, 2,-3') == [1,2,-3]
for s in ['', '1,', 'a']:
    try:
        parse_csv_ints(s)
        raise AssertionError(s)
    except ValueError:
        pass

assert unique_sorted([3,1,3,2]) == [1,2,3]
for v in ([True], ['1']):
    try:
        unique_sorted(v)
        raise AssertionError(v)
    except ValueError:
        pass

d={'a':{'b':3}}
assert deep_get(d,'a.b') == 3
assert deep_get(d,'a.x','z') == 'z'
assert deep_get(d,'') is None
assert d == {'a':{'b':3}}

assert roman_to_int('III') == 3
assert roman_to_int('IV') == 4
assert roman_to_int('MCM') == 1900
for s in ['', 'AX']:
    try:
        roman_to_int(s)
        raise AssertionError(s)
    except ValueError:
        pass

assert retry_delays(4,0.5) == [0.5,1.0,2.0,4.0]
for a,b in [(-1,1),(1,0)]:
    try:
        retry_delays(a,b)
        raise AssertionError()
    except ValueError:
        pass

assert parse_env(['A=1',' B=x=y',' # no','']) == {'A':'1','B':'x=y'}
try:
    parse_env(['BAD'])
    raise AssertionError()
except ValueError:
    pass

assert parse_hex('0x10') == 16
assert parse_hex('ff') == 255
for s in ['', '-1', '0xGG']:
    try:
        parse_hex(s)
        raise AssertionError(s)
    except ValueError:
        pass

assert group_by([{'k':'a','v':1},{'k':'b','v':2},{'k':'a','v':3}],'k') == {'a':[{'k':'a','v':1},{'k':'a','v':3}],'b':[{'k':'b','v':2}]}
try:
    group_by([{}],'k')
    raise AssertionError()
except KeyError:
    pass

assert pairs_to_dict([('a',1),('b',2)]) == {'a':1,'b':2}
try:
    pairs_to_dict([('a',1,2)])
    raise AssertionError()
except ValueError:
    pass

assert histogram([1,2,5,8],[2,5]) == [2,1,1]
try:
    histogram([1],[2,2])
    raise AssertionError()
except ValueError:
    pass

assert split_query('a=1&b=two') == {'a':'1','b':'two'}
try:
    split_query('a=1&a=2')
    raise AssertionError()
except ValueError:
    pass

assert parse_ini(['[a]','x=1','[b]','y=2']) == {'a':{'x':'1'},'b':{'y':'2'}}
for x in (['x=1'], ['[a]','x=1','x=2']):
    try:
        parse_ini(x)
        raise AssertionError()
    except ValueError:
        pass

assert require_keys({'a':1,'b':2},['b','a']) is None
try:
    require_keys({'a':1},['b','c'])
    raise AssertionError()
except KeyError as e:
    assert e.args[0] == 'b'
